// ==========================================
// CleanRules — 必须在主入口 IIFE 之前声明
// const 没有变量提升，放在后面会触发 TDZ 报错
// ==========================================
const CLEAN_RULES = {
  "video/adv/mainPageDialog":    ["Data"],
  "reddot/getdot":               ["Data"],
  "checkin/checkinexchangepage": ["Data.Goods"]
};

// ==========================================
// 🚀 主入口
// ==========================================
!(async () => {
  if (typeof $request === "undefined") {
    await executeCronTasks();
    // ⚠️ 修复(v5.9): 确保 cron 任务完成后调用 $.done(), 否则宿主进程挂起
    $.done();
    return;
  }

  const { url, method } = $request;

  // Z. High-level checkin cookie capture (getlogininfo)
  // ⚠️ 修复(v6.2): 使用 typeof 防止 ReferenceError
  if (url.includes("/user/getlogininfo") && typeof $response !== "undefined") {
    runQdreaderEngine();
    // ⚠️ 修复: 等待引擎捕获 Cookie 完成（不等待会导致 Cookie 写入前宿主就结束）
    await $.wait(5000);
    $.done();
    return;
  }

  // A. Token 窃取 (request 阶段，匹配 getconf/checkin)
  // ⚠️ 修复(v6.2): 使用 typeof 防止 Loon request 阶段 $response 变量未定义 ReferenceError
  if ((url.includes("/client/getconf") || url.includes("/checkin/")) && url.includes("magev6") && typeof $response === "undefined") {
    handleTokenSteal($request);
    return;
  }
  // A2. getconf response 覆写 — 删除悬浮广告字段
  if (url.includes("/client/getconf") && typeof $response !== "undefined") {
    handleClientConfig($response);
    return;
  }
  // B. GDT 视频拦截 — 返回 1 秒视频
  if (url.includes(".mp4") && (url.includes("gdtimg.com") || url.includes("gtimg.cn"))) {
    handleVideoReplace();
    return;
  }
  // C. 广告 SDK 秒播
  if (url.includes("/gdt_inner_view") || url.includes("/get_ads")) {
    // ⚠️ 修复(v5.9): 添加 $response 守卫, 防止 request 阶段误入 response 处理
    if (typeof $response === "undefined") { $.done(); return; }
    handleAdSkip($response);
    return;
  }

  const pathMatch = /^https?:\/\/[^/?#]+(\/[^?#]*)?(?:[?#]|$)/i.exec(url);
  if (!pathMatch) { $.done(); return; }
  const path = pathMatch[1] || "/";

  // ⚠️ 修复(v6.0): 统一 $response 守卫 — 防止 request 阶段误入 response-only 处理
  // AllInOne.plugin 等全局 MitM 规则可能让同一 URL 在 request 阶段也被匹配，
  // 此时 $response 为 undefined，直接调用会导致 ReferenceError 崩溃
  // ⚠️ 修复(v6.2): $response 守卫必须在 finishWatch(request) 检查之后，
  // 否则 finishWatch 的 request 阶段处理会被误杀（v6.0 回归 bug）
  if (typeof $response === "undefined" && !path.endsWith("/video/adv/finishWatch")) { $.done(); return; }

  // D. 直接拒绝纯广告端点
  if (CONFIG.RejectPaths.some(p => path.includes(p))) {
    handleReject();
    return;
  }
  // E. 自动重放
  if (path.endsWith("/video/adv/finishWatch") && method === "POST") {
    await handleReplay($request);
    return;
  }
  // F. 开屏广告
  if (path.includes("getsplashscreen")) {
    handleSplashScreen($response);
    return;
  }
  // G. Deeplink
  if (path.includes("deeplink/geturl")) {
    handleDeeplink($response);
    return;
  }
  // H. 每日推荐 — v4.0.3: getdailyrecommend 放行（恢复每日导读），其余一族维持原路径
  if (path.includes("dailyrecommend")) {
    if (path.includes("getdailyrecommend")) {
      // 每日导读恢复（用户裁决 2026-11-10）：不清空 Items，直接透传
      $.done();
      return;
    }
    handleDailyRec($response);
    return;
  }
  // I. 我的账户页
  if (path.includes("getaccountpage")) {
    handleAccountPage($response);
    return;
  }
  // J. 批量广告
  if (path.includes("adv/getadvlistbatch")) {
    handleAdListBatch(url, $response);
    return;
  }
  // K. 直接置空广告
  if (CONFIG.DirectKillPaths.some(p => path.includes(p))) {
    handleDirectAdKill(url, $response);
    return;
  }
  // L. 福利中心主页 — 标记任务已完成，不清空
  if (path.includes("video/adv/mainPage") && !path.includes("Dialog")) {
    handleMainPage($response);
    return;
  }
  // M. 发现页 — 按白名单过滤
  if (path.includes("getsimplediscover")) {
    handleDiscover($response);
    return;
  }
  // N. 书架悬浮广告
  if (path.includes("getHoverAdv")) {
    handleHoverAdv($response);
    return;
  }
  // O. 每日阅读积分
  if (path.includes("readtime/readpage")) {
    handleReadTime($response);
    return;
  }
  // P. 其余净化规则
  if (matchCleanRule(path)) {
    handleClean(path, $response);
    return;
  }

  $.done();

})().catch(e => {
  $.log(`异常: ${e}`);
  $.done();
});

// ==========================================
// 🛠️ 核心函数
// ==========================================

function handleTokenSteal(request) {
  try {
    if (request.headers) {
      $.set(request.headers, "Qidian_Headers");
      $.log("✨ 已保存起点 Token");
    }
    $.done();
  } catch (e) {
    $.done();
  }
}

function handleClientConfig(response) {
  try {
    const obj = safeJsonParse(response.body);
    if (!obj || !obj.Data) { $.done(); return; }

    for (const [k, v] of Object.entries(CONFIG.ClientConfigOverrides)) {
      obj.Data[k] = v;
    }
    CONFIG.DeleteKeys.forEach(k => { delete obj.Data[k]; });

    // 关闭发现 tab（NewFeedsDiscover=0 已由 getconf 服务端返回，此处强制确保）
    obj.Data.NewFeedsDiscover = 0;

    if (obj.Data.CloudSetting && obj.Data.CloudSetting.TeenShowFreq) {
      obj.Data.CloudSetting.TeenShowFreq = "0";
    }
    if (obj.Data.GDT) delete obj.Data.GDT;

    $.log("✨ 已覆盖客户端配置");
    $.done({ body: JSON.stringify(obj) });
  } catch (e) {
    $.log(`❌ 配置覆写失败: ${e}`);
    $.done();
  }
}

/**
 * 福利中心主页 — 按用户选择保留/删除各模块
 * 保留: DailyBenefitModule(激励任务), VideoRewardTab(视频奖励),
 *       RedeemGifts(积分兑换), ScoreDrawModule(幸运抽抽乐)
 * 删除: MemberExclusiveTaskModule(会员尊享), PrivilegedTaskModule(邀好友),
 *       MoreRewardTab(更多奖励), SurpriseBenefit(限时福利),
 *       LastRewardItems(必中夺宝), IndexBannerTabs(顶部Banner)
 */
function handleMainPage(response) {
  try {
    const obj = safeJsonParse(response.body);
    if (!obj || !obj.Data) { $.done(); return; }
    const data = obj.Data;

    // ── 激励任务：不修改 IsFinished，保留原始状态让用户手动触发视频 ──
    if (data.DailyBenefitModule) {
      data.DailyBenefitModule.RotateText = [];
    }

    // ── 视频奖励 tab：同样保留原始状态 ─────────────────────

    // ── 保留：RedeemGifts(积分兑换), ScoreDrawModule(幸运抽抽乐) ──

    // ── 删除：营销/活动/邀请/会员/限时模块 ───────────────
    const REMOVE_KEYS = [
      "MemberExclusiveTaskModule", // 会员尊享（90天畅读等）
      "PrivilegedTaskModule",      // 邀好友活动（邀友一起读/3300点等）
      "MoreRewardTab",             // 更多奖励（关注微信服务号等）
      "SurpriseBenefit",           // 限时福利
      "LastRewardItems",           // 必中夺宝
      "IndexBannerTabs",           // 顶部 banner
      "BaizeModule",               // 白泽装扮气泡
      "TaskShowData",              // 任务展示配置
      "UserRewardModule",          // 用户奖励统计
      "PopFrequency",              // 弹窗频率控制
    ];
    REMOVE_KEYS.forEach(k => { delete data[k]; });

    $.log("✨ 福利中心已净化");
    $.done({ body: JSON.stringify(obj) });
  } catch (e) { $.done(); }
}

// ── LOCAL PATCH (AshNail/plugins v4.0.0)：限时激励任务收集 ──
// 收集 ReadingPageTaskModule 中的限时任务（TaskType 300，
// 标题「【限时】广告·加点！」），返回 [{id, total, title}]。
function collectLimitedTasks(data) {
  const out = [];
  const seen = {};
  const add = (it) => {
    if (!it || typeof it !== "object") return;
    const title = typeof it.Title === "string" ? it.Title : "";
    const isLimited = it.TaskType === 300 || String(it.TaskType) === "300" ||
      (it.TaskType === undefined && (title.indexOf("限时") >= 0 || /广告[·.]?加点/.test(title)));
    if (!isLimited) return;
    const id = it.TaskId || it.SubTaskId;
    if (!id || seen[String(id)]) return;
    seen[String(id)] = true;
    out.push({
      id: String(id),
      total: Number(it.Total) > 0 ? Number(it.Total) : 1,
      title: title || "限时激励",
    });
  };
  const mod = data.ReadingPageTaskModule;
  if (mod && Array.isArray(mod.TaskList)) mod.TaskList.forEach(add);
  return out;
}

