// ⏰ Cron 签到 & 福利抽奖
// ==========================================
async function checkinLottery(headers) {
  try {
    const res = await $.fetch({
      url: "https://magev6.if.qidian.com/argus/api/v1/checkin/checkinlottery",
      method: "POST",
      headers: normalizeHeaders(headers),
      body: "",
      timeout: 10000 // v6.3: 防止抽奖请求挂起阻塞引擎启动
    });
    if (res && res.statusCode === 200) {
      const obj = safeJsonParse(res.body);
      if (obj && obj.Result === 0) {
        return ` | 🎁 抽奖: ${obj.Data?.AwardName || "成功"}`;
      } else {
        return ` | 🎁 抽奖: ${obj.Message || "无奖励"}`;
      }
    }
  } catch (e) {
    return ` | 🎁 抽奖异常: ${e}`;
  }
  return "";
}

async function handleSimpleCheckin() {
  const headers = $.get("Qidian_Headers");
  if (!headers) {
    $.log("⚠️ 未找到简单签到 Token，跳过简单签到");
    return "missing";
  }

  // v6.3 修复: 快速失败策略 — 最多 2 次尝试，单次 10s 超时，间隔 1.5s
  // 历史问题: 3 次重试 × 无超时 → 凌晨 DNS 慢时消耗 68s，引擎启动过晚
  // 目标: 签到阶段 ≤15s，确保引擎在 cron 启动后 20s 内开始执行
  const maxRetry = 2;
  const perRequestTimeout = 10000; // 10s 单次超时
  let lastError = "";
  for (let i = 0; i < maxRetry; i++) {
    try {
      const res = await $.fetch({
        url: "https://magev6.if.qidian.com/argus/api/v2/checkin/checkin",
        method: "POST",
        headers: normalizeHeaders(headers),
        body: "",
        timeout: perRequestTimeout
      });

      if (res && res.statusCode === 200) {
        const obj = safeJsonParse(res.body);
        if (obj && obj.Result === 0) {
          const drawMsg = await checkinLottery(headers);
          if (!CONFIG.SilentMode) {
            $.notify("起点助手", "✅ 签到成功", (obj.Message || "今日签到完成") + drawMsg);
          } else {
            $.log(`[静默模式] ✅ 签到成功: ${(obj.Message || "今日签到完成") + drawMsg}`);
          }
          return "ok";
        } else if (obj && obj.Result === -452000) {
          const drawMsg = await checkinLottery(headers);
          if (!CONFIG.SilentMode) {
            $.notify("起点助手", "📅 今日已签到", (obj.Message || "今日已签到") + drawMsg);
          } else {
            $.log(`[静默模式] 📅 今日已签到: ${(obj.Message || "今日已签到") + drawMsg}`);
          }
          return "ok";
        } else {
          const msg = obj ? JSON.stringify(obj) : "未知错误";
          if (!CONFIG.SilentMode) {
            $.notify("起点助手", "⚠️ 签到异常", msg);
          } else {
            $.log(`[静默模式] ⚠️ 签到异常: ${msg}`);
          }
          return "failed";
        }
      }
      // v6.4: Token 过期短路 — 401/403 说明 Cookie 已失效，重试无意义，
      // 直接通知并返回 expired，调用方跳过引擎 + 400s 等待
      const code = res ? res.statusCode : 0;
      if (code === 401 || code === 403) {
        const msg = "Cookie 已过期，请重新打开起点 App 触发抓取 (getlogininfo)";
        if (!CONFIG.SilentMode) {
          $.notify("起点助手", "🔑 Cookie过期", msg);
        } else {
          $.log(`[静默模式] 🔑 Cookie过期: ${msg}`);
        }
        return "expired";
      }
      // res 存在但 statusCode 非 200/401/403 (如 429/502/503)
      lastError = `HTTP ${res ? res.statusCode : "未知"}`;
      if (i < maxRetry - 1) {
        $.log(`[签到] ${lastError}, 重试 ${i + 1}/${maxRetry}...`);
        await $.wait(1500);
      }
    } catch (e) {
      lastError = String(e);
      if (i === maxRetry - 1) {
        const errMsg = '重试' + maxRetry + '次后仍失败: ' + lastError;
        if (!CONFIG.SilentMode) {
          $.notify("起点助手", "❌ 签到失败", errMsg);
        } else {
          $.log(`[静默模式] ❌ 签到失败: ${errMsg}`);
        }
      } else {
        $.log(`[签到] 网络异常, 重试 ${i + 1}/${maxRetry}...`);
        await $.wait(1500);
      }
    }
  }
  // 重试全部失败 — 兜底通知（不阻塞引擎启动）
  const errMsg = '重试' + maxRetry + '次后仍失败 (HTTP ' + lastError + ')';
  if (!CONFIG.SilentMode) {
    $.notify("起点助手", "❌ 签到失败", errMsg);
  } else {
    $.log(`[静默模式] ❌ 签到失败: ${errMsg}`);
  }
  return "failed";
}

// v6.4: 高阶任务开关全关即纯签到模式 — 跳过引擎 + 400s 等待。
// $argument 缺失 (如单测/手动调用) 按默认全开处理，保持全量等待。
function engineTaskSwitchesOff() {
  try {
    normalizeGlobalArgument();
    const arg = (typeof globalThis !== "undefined" && globalThis.$argument) || (typeof $argument !== "undefined" && $argument);
    if (!arg) return false;
    const off = (k) => String(arg[k]) === "false";
    return off("QDREADER_ADV_JOB_ENABLE")
      && off("QDREADER_EXTRA_ADV_JOB_ENABLE")
      && off("QDREADER_LOTTERY_ENABLE")
      && off("QDREADER_WEEKLY_EXCHANGE_ENABLE");
  } catch (e) { return false; }
}

async function executeCronTasks() {
  $.log("⚙️ 开始执行起点简单签到...");
  const signResult = await handleSimpleCheckin();
  // v6.4 短路: Token 过期直接结束，省去 DNS 预热 + 引擎 + 400s 空等
  if (signResult === "expired") {
    $.log("⏭️ Token 已过期，跳过高阶引擎 (省 400s 等待)");
    return;
  }
  // v6.4 超时拆分: 高阶开关全关 = 纯签到，跳过引擎
  if (engineTaskSwitchesOff()) {
    $.log("⏭️ 高阶任务开关全关，纯签到模式，跳过引擎");
    return;
  }
  $.log("⚙️ 开始执行起点高阶任务...");

  // v6.3: DNS 预热 — 在引擎启动前预建连接，减少引擎首次请求的 DNS 延迟
  // 历史问题: 凌晨 DNS 解析慢（DoH3 超时回退），引擎首次请求挂起 60s+
  // LOCAL PATCH (AshNail/plugins v4.0.0)：预热响应同时当作限时激励任务源——
  // cron 跑在后台，用户不一定打开过福利中心；不在这里收集，finishWatch
  // 的动态 TaskMapping 就会为空，限时任务只能等下一次 App 主动请求 mainPage。
  try {
    const warm = await $.fetch({
      url: "https://h5.if.qidian.com/argus/api/v2/video/adv/mainPage",
      method: "GET",
      headers: normalizeHeaders($.get("Qidian_Headers") || {}),
      timeout: 8000
    });
    $.log("✨ DNS 预热完成");
    try {
      const warmObj = safeJsonParse(warm && warm.body);
      if (warmObj && warmObj.Data) {
        const limited = collectLimitedTasks(warmObj.Data);
        if (limited.length) {
          $.set(JSON.stringify(limited), "Qidian_LimitedTasks");
          $.log(`✨ 预热收集限时任务=${limited.length} [` +
            limited.map(t => t.id + "*" + t.total).join(" / ") + "]");
        }
      }
    } catch (e) { /* 预热体解析失败不影响引擎 */ }
  } catch (e) {
    $.log(`⚠️ DNS 预热失败(不影响引擎): ${e}`);
  }

  // ⚠️ 修复: runQdreaderEngine 内部 eval 注入异步引擎，无法真正 await
  // 但需要给引擎足够的执行时间，否则宿主会在引擎异步 fetch 进行中回收上下文
  runQdreaderEngine();
  // v6.3: 等待引擎执行 — 激励×9 + 每日×5 次 finishWatch，每步随机等待 5-10s，
  // 全量需 2-3 分钟。等 400s（略低于插件 TIMEOUT=420），避免引擎中途被截断
  // （历史 bug: 30s 等待 + 60s 超时 → 激励 7/9、每日任务 0/3）
  // （v6.2 bug: 280s 等待 + 300s 超时 - 68s checkin = 引擎只有 212s → 激励 8/9）
  await $.wait(400000);
}

// ==========================================
// 🔧 工具函数
// ==========================================
function normalizeHeaders(headers = {}) {
  const h = { ...headers };
  delete h["Content-Length"];
  delete h["content-length"];
  return h;
}

function patchDurationFields(value, keys, nextValue) {
  if (!value || typeof value !== "object") return;
  if (Array.isArray(value)) {
    value.forEach(item => patchDurationFields(item, keys, nextValue));
    return;
  }
  if (value.name && CONFIG.RewardTimeKeys.includes(value.name) && Array.isArray(value.data)) {
    value.data.forEach(d => {
      if (d && d.data && d.data.int_val !== undefined) d.data.int_val = String(nextValue);
    });
  }
  for (const [key, item] of Object.entries(value)) {
    if (keys.includes(key)) {
      if (typeof item === "number") { value[key] = nextValue; continue; }
      if (typeof item === "string" && !isNaN(item)) { value[key] = String(nextValue); continue; }
    }
    patchDurationFields(item, keys, nextValue);
  }
}

function parseSelector(segment) {
  const match = /^([^[\]]+)(?:\[([^=\]]+)=([^\]]+)\])?$/.exec(segment);
  if (!match) return { key: segment };
  return { key: match[1], filterKey: match[2], filterValue: match[3] };
}

function applyCleanRule(target, segments, index = 0) {
  if (!target || index >= segments.length) return;
  const { key, filterKey, filterValue } = parseSelector(segments[index]);
  const current = target[key];
  if (current == null) return;
  if (index === segments.length - 1) {
    if (filterKey && Array.isArray(current)) {
      target[key] = current.filter(item => String(item?.[filterKey]) !== filterValue);
      return;
    }
    delete target[key];
    return;
  }
  if (filterKey && Array.isArray(current)) {
    current.filter(item => String(item?.[filterKey]) === filterValue)
           .forEach(item => applyCleanRule(item, segments, index + 1));
    return;
  }
  applyCleanRule(current, segments, index + 1);
}

function safeJsonParse(body) {
  try {
    // 直接解析（字符串或已解压的内容）
    if (typeof body === "string") {
      return JSON.parse(body);
    }
    // Uint8Array：先转字符串再解析
    if (body instanceof Uint8Array) {
      const text = new TextDecoder("utf-8").decode(body);
      return JSON.parse(text);
    }
    // ArrayBuffer：转 Uint8Array 再处理
    if (body instanceof ArrayBuffer) {
      const text = new TextDecoder("utf-8").decode(new Uint8Array(body));
      return JSON.parse(text);
    }
    return null;
  } catch (e) {
    // 可能是 gzip 压缩的字节，尝试解压
    try {
      if (typeof $utils !== "undefined" && $utils.ungzip) {
        let bytes = body;
        if (typeof body === "string") {
          // 字符串可能是 gzip 字节的错误解码，尝试转回字节
          bytes = new TextEncoder().encode(body);
        }
        if (bytes instanceof ArrayBuffer) {
          bytes = new Uint8Array(bytes);
        }
        if (bytes instanceof Uint8Array) {
          const decompressed = $utils.ungzip(bytes);
          const text = typeof decompressed === "string" 
            ? decompressed 
            : new TextDecoder("utf-8").decode(decompressed);
          return JSON.parse(text);
        }
      }
    } catch (e2) {
      // ungzip 也失败，返回 null
    }
    return null;
  }
}

// ==========================================
// 🌍 Env 兼容层 (Loon)
// ==========================================
function Env(n) {
  this.name = n;
  this.isL = typeof $loon !== "undefined";
  this.log = (...a) => console.log(`[${this.name}] ` + a.join(" "));
  this.wait = (m) => new Promise(r => setTimeout(r, m));
  this.done = (o = {}) => $done(o);
  this.get = (k) => {
    let v = $persistentStore.read(k);
    try { return JSON.parse(v); } catch (e) { return v; }
  };
  this.set = (v, k) => {
    let s = typeof v === "object" ? JSON.stringify(v) : v;
    $persistentStore.write(s, k);
  };
  this.fetch = async (o) => new Promise((r, e) => {
    let m = (o.method || "GET").toLowerCase();
    $httpClient[m](o, (err, res, b) => {
      if (err) e(err);
      else {
        res.body = b;
        // ⚠️ 修复: Loon 的 response 字段名在不同版本可能是 status 或 statusCode
        // 不能用 || 200 兜底，否则 4xx/5xx 也会被误判为成功
        if (res.statusCode === undefined) {
          res.statusCode = res.status !== undefined ? res.status : (res.response ? res.response.statusCode : 200);
        }
        r(res);
      }
    });
  });
  this.notify = (t, s, b) => {
    // 掩码统一到模块级 maskSecrets (与全局出口掩码共用一份规则, 避免两处模式漂移)。
    // 此处仍需显式调用: **远程推送** (Bark/TG/PushPlus) 不走 $notification.post,
    // 不会被全局出口掩码覆盖。
    t = maskSecrets(t); s = maskSecrets(s); b = maskSecrets(b);

    // 1. 本地通知
    $notification.post(t, s, b);

    // 2. 远程推送 (Bark, Telegram, PushPlus)
    // 返回 Promise — 响应阶段调用方必须 await 后再 $done(),
    // 否则上下文回收会中止未完成的推送 (历史 bug: 推送全部静默失败)
    const barkKey = this.get("Bark_Key") || this.get("barkKey");
    const tgToken = this.get("TG_BOT_TOKEN") || this.get("tgToken");
    const tgChatId = this.get("TG_USER_ID") || this.get("tgChatId");
    const pushplusToken = this.get("PUSHPLUS_TOKEN") || this.get("pushplusToken");

    const pushes = [];
    if (barkKey) {
      pushes.push(this.fetch({
        url: `https://api.day.app/${barkKey}/${encodeURIComponent(t)}/${encodeURIComponent((s ? s + "\n" : "") + b)}`,
        method: "GET"
      }).then(() => this.log("Bark 推送成功")).catch(e => this.log("Bark 推送失败: " + e)));
    }
    if (tgToken && tgChatId) {
      pushes.push(this.fetch({
        url: `https://api.telegram.org/bot${tgToken}/sendMessage`,
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          chat_id: String(tgChatId),
          text: `${t}\n${s ? s + "\n" : ""}${b}`
        })
      }).then(() => this.log("Telegram 推送成功")).catch(e => this.log("Telegram 推送失败: " + e)));
    }
    if (pushplusToken) {
      pushes.push(this.fetch({
        url: "https://www.pushplus.plus/send",
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          token: String(pushplusToken),
          title: t,
          content: `${s ? s + "\n" : ""}${b}`
        })
      }).then(() => this.log("PushPlus 推送成功")).catch(e => this.log("PushPlus 推送失败: " + e)));
    }
    return Promise.allSettled(pushes);
  };
}


